"""Serial CPU state exporter: parsed policy rules -> canonical live-state image.

The exported image is the minimal deterministic complete machine of the policy
language after removal of its dead residual.  Columns follow the registry in
increasing label order; DENY is the integer target of every dead transition and
carries no row.  Retained residuals are numbered by breadth-first discovery
from START scanning columns in increasing label order and ignoring DENY.
"""

from syntax import iter_atoms

DENY = 4294967295
MAX_ROWS = 8192


class ImageError(ValueError):
    """Registry violation or an image that exceeds the exported row bound."""


def _convert(tree, index):
    """Rewrite every path into registry columns, rejecting unknown names."""
    kind = tree[0]
    if kind == 'atom':
        try:
            return ('atom', tree[1], tuple([index[name] for name in tree[2]]))
        except KeyError:
            raise ImageError('unregistered service') from None
    if kind == 'n':
        return ('n', _convert(tree[1], index))
    return ('b', tree[1], _convert(tree[2], index), _convert(tree[3], index))


def _suffix(prefix, count, tail):
    """True when ``prefix[:count]`` is a suffix of ``tail``."""
    if count == 0:
        return True
    size = len(tail)
    if count > size:
        return False
    return tail[size - count:] == prefix[:count]


def _atom_machine(op, path, width):
    """Deterministic machine of one non-`match` atom over ``width`` columns.

    Returns ``(table, accepting_state)``.  ``startswith`` keeps one extra dead
    state; ``endswith`` and ``contains`` use the KMP border automaton, with
    ``contains`` absorbing at its final state.
    """
    size = len(path)
    states = size + (2 if op == 'startswith' else 1)
    table = []
    for state in range(states):
        row = []
        for column in range(width):
            if op == 'startswith':
                if state == size:
                    row.append(state)
                elif state < size and column == path[state]:
                    row.append(state + 1)
                else:
                    row.append(size + 1)
            else:
                if op == 'contains' and state == size:
                    row.append(state)
                else:
                    head = path[:state] + (column,)
                    reached = min(state + 1, size)
                    while not _suffix(path, reached, head):
                        reached -= 1
                    row.append(reached)
        table.append(row)
    return table, size


def _compile_pred(tree, words, xpos, xacc):
    """Closure evaluating a predicate for one machine state."""
    kind = tree[0]
    if kind == 'atom':
        if tree[1] == 'match':
            node = words[tree[2]]
            return lambda state, live: state == node
        slot = xpos[tree[2]]
        final = xacc[slot]
        return lambda state, live: live[slot] == final
    if kind == 'n':
        inner = _compile_pred(tree[1], words, xpos, xacc)
        return lambda state, live: not inner(state, live)
    left = _compile_pred(tree[2], words, xpos, xacc)
    right = _compile_pred(tree[3], words, xpos, xacc)
    if tree[1] == 'and':
        return lambda state, live: left(state, live) and right(state, live)
    return lambda state, live: left(state, live) or right(state, live)


def _minimize(count, table, flags):
    """Coarsest stable refinement of the acceptance partition."""
    marks = [1 if flag else 0 for flag in flags]
    classes = 2 if 1 in marks else 1
    while True:
        seen = {}
        fresh = [0] * count
        for state in range(count):
            key = (marks[state], tuple([marks[t] for t in table[state]]))
            label = seen.get(key)
            if label is None:
                label = len(seen)
                seen[key] = label
            fresh[state] = label
        marks = fresh
        if len(seen) == classes:
            return marks
        classes = len(seen)


def image(rules, symbols, index):
    """Return ``(accept, rows, cells)`` for the parsed rules of one registry."""
    width = len(symbols)
    converted = [(_convert(tree, index), flag) for tree, flag in rules]

    words = {}
    xpos = {}
    xatoms = []
    for tree, _flag in converted:
        for op, path in iter_atoms(tree):
            if op == 'match':
                if path not in words:
                    words[path] = None
            elif (op, path) not in xpos:
                xpos[(op, path)] = len(xatoms)
                xatoms.append((op, path))

    # Trie of every match word; one extra node collects all dead transitions.
    children = [{}]
    for word in list(words):
        node = 0
        for column in word:
            row = children[node]
            nxt = row.get(column)
            if nxt is None:
                nxt = len(children)
                children.append({})
                row[column] = nxt
            node = nxt
        words[word] = node
    dead = len(children)
    children.append(None)
    nodes = len(children)
    trie = [None] * nodes
    for node in range(nodes - 1):
        row = children[node]
        trie[node] = [row.get(column, dead) for column in range(width)]
    trie[dead] = [dead] * width
    children = None

    xtable = []
    xacc = []
    for op, path in xatoms:
        table, final = _atom_machine(op, path, width)
        xtable.append(table)
        xacc.append(final)

    if not xatoms:
        # Only match atoms: the trie itself is the reachable machine.
        total = nodes
        table = trie
        state_of_node = None
        states = None
        live = None
        initial = 0
    else:
        slots = len(xatoms)
        live_id = {}
        live_list = []
        live_row = []

        def intern(live):
            slot = live_id.get(live)
            if slot is None:
                slot = len(live_list)
                live_id[live] = slot
                live_list.append(live)
                live_row.append(None)
            return slot

        state_id = {}
        states = []
        state_of_node = {}

        def state(node, slot):
            key = (node, slot)
            found = state_id.get(key)
            if found is None:
                found = len(states)
                state_id[key] = found
                states.append(key)
            return found

        initial = state(0, intern(tuple([0] * slots)))
        pending = [initial]
        table = []
        cursor = 0
        while cursor < len(pending):
            source = pending[cursor]
            cursor += 1
            node, slot = states[source]
            row = live_row[slot]
            if row is None:
                current = live_list[slot]
                row = []
                for column in range(width):
                    nxt = tuple([xtable[i][current[i]][column]
                                 for i in range(slots)])
                    row.append(intern(nxt))
                live_row[slot] = row
            base = trie[node]
            transitions = []
            for column in range(width):
                target = state(base[column], row[column])
                transitions.append(target)
                if base[column] != dead and base[column] not in state_of_node:
                    state_of_node[base[column]] = target
            table.append(transitions)
        total = len(states)
        live = live_list
        trie = None

    # Classify rules and pre-evaluate every rule value the machine can take.
    complex_rules = []
    simple = []
    exceptional = set()
    for tree, flag in converted:
        if tree[0] == 'atom' and tree[1] == 'match':
            simple.append((words[tree[2]], flag))
            continue
        complex_rules.append((_compile_pred(tree, words, xpos, xacc), flag))
        for op, path in iter_atoms(tree):
            if op == 'match':
                exceptional.add(words[path])
    words = None

    if states is None:
        base_allow = False
        base_drop = False
        for evaluate, flag in complex_rules:
            if evaluate(-1, ()):
                if flag:
                    base_allow = True
                else:
                    base_drop = True
        allow = bytearray(total)
        drop = bytearray(total)
        if base_allow:
            allow[:] = b'\x01' * total
        if base_drop:
            drop[:] = b'\x01' * total
        allow_simple = set()
        drop_simple = set()
        for node, flag in simple:
            if flag:
                allow_simple.add(node)
            else:
                drop_simple.add(node)
        for node in allow_simple:
            allow[node] = 1
        for node in drop_simple:
            drop[node] = 1
        for node in exceptional:
            allow[node] = 1 if any(evaluate(node, ())
                                   for evaluate, flag in complex_rules
                                   if flag) or node in allow_simple else 0
            drop[node] = 1 if any(evaluate(node, ())
                                  for evaluate, flag in complex_rules
                                  if not flag) or node in drop_simple else 0
    else:
        present = sorted(set([slot for _node, slot in states]))
        sum_allow = {}
        sum_drop = {}
        for slot in present:
            current = live[slot]
            sum_allow[slot] = any(evaluate(-1, current)
                                  for evaluate, flag in complex_rules if flag)
            sum_drop[slot] = any(evaluate(-1, current)
                                 for evaluate, flag in complex_rules
                                 if not flag)
        allow = bytearray(total)
        drop = bytearray(total)
        for state_id_ in range(total):
            slot = states[state_id_][1]
            if sum_allow[slot]:
                allow[state_id_] = 1
            if sum_drop[slot]:
                drop[state_id_] = 1
        allow_simple = set()
        drop_simple = set()
        for node, flag in simple:
            target = state_of_node[node]
            if flag:
                allow_simple.add(target)
            else:
                drop_simple.add(target)
        for target in allow_simple:
            allow[target] = 1
        for target in drop_simple:
            drop[target] = 1
        for node in exceptional:
            target = state_of_node[node]
            current = live[states[target][1]]
            allow[target] = 1 if any(evaluate(node, current)
                                     for evaluate, flag in complex_rules
                                     if flag) or target in allow_simple else 0
            drop[target] = 1 if any(evaluate(node, current)
                                    for evaluate, flag in complex_rules
                                    if not flag) or target in drop_simple else 0
    for state_id_ in range(total):
        if drop[state_id_]:
            allow[state_id_] = 0

    # Retain only residuals that still reach an allowed sequence.
    reverse = [[] for _ in range(total)]
    for state_id_ in range(total):
        for target in table[state_id_]:
            reverse[target].append(state_id_)
    coaccessible = bytearray(total)
    pending = [state for state in range(total) if allow[state]]
    while pending:
        state = pending.pop()
        if coaccessible[state]:
            continue
        coaccessible[state] = 1
        pending.extend(reverse[state])
    reverse = None
    if not coaccessible[initial]:
        return [False], [[DENY] * width], 0

    keep = [state for state in range(total) if coaccessible[state]]
    where = {}
    for slot, state in enumerate(keep):
        where[state] = slot
    size = len(keep)
    kept = []
    for state in keep:
        kept.append([where.get(target, size) for target in table[state]])
    kept_flags = [allow[state] for state in keep]
    start = where[initial]
    sink = size in kept_transitions(kept)
    if sink:
        kept.append([size] * width)
        kept_flags.append(0)
    order = _minimize(size + (1 if sink else 0), kept, kept_flags)

    classes = max(order) + 1
    head = [-1] * classes
    for state in range(len(order)):
        label = order[state]
        if head[label] < 0:
            head[label] = state
    quotient = [[order[target] for target in kept[head[label]]]
                for label in range(classes)]
    flags = [kept_flags[head[label]] for label in range(classes)]
    deny = order[size] if sink else -1

    numbered = {order[start]: 0}
    queue = [order[start]]
    rows = []
    cursor = 0
    while cursor < len(queue):
        label = queue[cursor]
        cursor += 1
        row = []
        for column in range(width):
            target = quotient[label][column]
            if target == deny:
                row.append(DENY)
                continue
            seen = numbered.get(target)
            if seen is None:
                seen = len(numbered)
                numbered[target] = seen
                queue.append(target)
            row.append(seen)
        rows.append(row)
    if len(rows) > MAX_ROWS:
        raise ImageError('image row bound')
    cells = 0
    for row in rows:
        for target in row:
            if target != DENY:
                cells += 1
    return [bool(flags[label]) for label in queue], rows, cells


def kept_transitions(kept):
    for row in kept:
        for target in row:
            if target == len(kept):
                return True
    return False
